package dev.admutium.techmod.suit;
import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;
public final class SuitInventoryMenu extends AbstractContainerMenu {
 public final SuitSession session;public final Container cargo;
 public SuitInventoryMenu(int id,Inventory inv){this(id,inv,null);}
 public SuitInventoryMenu(int id,Inventory inv,SuitSession s){super(Suits.INVENTORY_MENU,id);session=s;cargo=new SimpleContainer(9){public ItemStack getItem(int i){return s==null?super.getItem(i):s.cargo.get(i);}public void setItem(int i,ItemStack stack){if(s==null)super.setItem(i,stack);else{s.cargo.set(i,stack);s.flush();}}public ItemStack removeItem(int i,int n){if(s==null)return super.removeItem(i,n);var stack=s.cargo.get(i).split(n);s.flush();return stack;}public void setChanged(){if(s!=null)s.flush();}};for(int i=0;i<9;i++)addSlot(new Slot(cargo,i,12+i*18,44){public boolean mayPlace(ItemStack stack){return !stack.is(Suits.ITEM)&&(s==null||s.level(SuitUpgrade.INVENTORY)>0);}});var capsules=new SimpleContainer(1){public ItemStack getItem(int i){return s==null?super.getItem(i):s.nutrients==0?ItemStack.EMPTY:new ItemStack(Suits.NUTRIENT,Math.min(64,s.nutrients));}};
 addSlot(new Slot(capsules,0,12,70){public boolean mayPlace(ItemStack item){return false;}public boolean mayPickup(Player p){return false;}});var equipped=new SimpleContainer(1);if(s!=null)equipped.setItem(0,s.stack);addSlot(new Slot(equipped,0,156,70){public boolean mayPlace(ItemStack item){return false;}public boolean mayPickup(Player p){return false;}});addStandardInventorySlots(inv,12,108);}
 @Override public void clicked(int slot,int button,ContainerInput action,Player p){if(slot==9){if(session==null||!stillValid(p))return;if(action==ContainerInput.PICKUP){var carried=getCarried();if(carried.is(Suits.NUTRIENT)){int n=Math.min(carried.getCount(),32*session.level(SuitUpgrade.NUTRIENTS)-session.nutrients);if(button==1)n=Math.min(1,n);if(n>0){carried.shrink(n);session.nutrients+=n;}}else if(carried.isEmpty()){int n=Math.min(button==1?1:64,session.nutrients);if(n>0){setCarried(new ItemStack(Suits.NUTRIENT,n));session.nutrients-=n;}}session.flush();}else if(action==ContainerInput.QUICK_MOVE){var stack=new ItemStack(Suits.NUTRIENT,Math.min(64,session.nutrients));int n=stack.getCount();p.getInventory().add(stack);session.nutrients-=n-stack.getCount();session.flush();}return;}super.clicked(slot,button,action,p);}
 public boolean stillValid(Player p){return session==null||Suits.session(p)==session;}
 public ItemStack quickMoveStack(Player p,int i){var slot=slots.get(i);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var copy=stack.copy();if(i==9||i==10)return ItemStack.EMPTY;if(i<9){if(!moveItemStackTo(stack,11,slots.size(),true))return ItemStack.EMPTY;}else if(stack.is(Suits.NUTRIENT)&&session!=null){int n=Math.min(stack.getCount(),32*session.level(SuitUpgrade.NUTRIENTS)-session.nutrients);if(n<=0)return ItemStack.EMPTY;stack.shrink(n);session.nutrients+=n;session.flush();}else if(stack.is(Suits.ITEM)||!moveItemStackTo(stack,0,9,false))return ItemStack.EMPTY;if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();return copy;}
 public void removed(Player p){super.removed(p);if(session!=null)session.flush();}
}
